INSERT INTO `events` VALUES (1,'728e395d-730a-47cf-9b50-e93c911930a5',1,'هل أنتم مستعدون لاكتشاف أفضل المهارات في الجزائر؟','Olympiades des Métiers Afrique 2026','African Skills Competition 2026','national-opening-ceremony-2027','انضموا إلينا في \"أولمبياد المهن\"، حيث ستتبارى المهارات الجزائرية في منافسات مختلفة لإبراز قدراتها. هذه فرصتكم لتكونوا جزءًا من حدث وطني يحتفي بكم، وتابعوا مراحل التصفيات الولائية والجهوية وصولاً إلى النهائيات الوطنية في ولاية وهران. اكتشفوا تفاصيل أولمبياد المهن في الموقع الرسمي للمسابقة.','Du 25 au 30 Novembre 2026 — Alger','Gathering of national and international delegations at Mohamed Ben Ahmed Convention Center, Oran.',NULL,NULL,NULL,'2026-08-14 14:28:19',NULL,'المركز الدولي للمؤتمرات عبد اللطيف رحال','بن عكنون - الجزائر العاصمة',NULL,NULL,0,1,'PUBLISHED','2026-08-12 23:04:38','2026-08-04 10:27:37','2026-08-14 13:28:19');
/*!40000 ALTER TABLE `events` ENABLE KEYS */;
