INSERT INTO `global_settings` VALUES (1,'home_hero_title_ar','هل أنتم مستعدون لاكتشاف أفضل المهارات في الجزائر؟','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-07 19:00:38'),(2,'home_hero_title_fr','Olympiades des Métiers Afrique 2026','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(3,'home_hero_title_en','African Skills Competition 2026','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(4,'home_hero_subtitle_ar','انضموا إلينا في \"أولمبياد المهن\"، حيث ستتبارى المهارات الجزائرية في منافسات مختلفة لإبراز قدراتها. هذه فرصتكم لتكونوا جزءًا من حدث وطني يحتفي بكم، وتابعوا مراحل التصفيات الولائية والجهوية وصولاً إلى النهائيات الوطنية في ولاية وهران. اكتشفوا تفاصيل أولمبياد المهن في الموقع الرسمي للمسابقة.','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-07 19:00:38'),(5,'home_hero_subtitle_fr','Du 25 au 30 Novembre 2026 — Alger','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(6,'home_hero_subtitle_en','25 to 30 November 2026 — Algiers','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(7,'home_cta_text_ar','كن جزءاً من أكبر حدث للمهارات في إفريقيا!','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(8,'home_cta_text_fr','Faites partie du plus grand événement des compétences en Afrique!','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(9,'home_cta_text_en','Be part of the largest skills event in Africa!','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(10,'featured_video_url','https://www.youtube.com/embed/ee7fzNFUKIM','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-18 20:40:53'),(11,'featured_video_title_ar','أجواء أولمبياد المهن العالمي بالجزائر','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(12,'featured_video_title_fr','Ambiance des Olympiades des Métiers en Algérie','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(13,'featured_video_title_en','WorldSkills Competition Highlights Algeria','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(14,'countdown_title_ar','العد التنازلي لافتتاح منتدى المهارات الإفريقية 2026','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-13 00:09:46'),(15,'countdown_title_fr','Décompte du Lancement d\'Africa Skills Forum 2026','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-13 00:09:46'),(16,'countdown_title_en','Countdown to Africa Skills Forum 2026','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-13 00:09:46'),(17,'countdown_target_date','2026-11-25 09:00:00','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:51:50'),(18,'countdown_enabled','1','string','general',NULL,1,NULL,'2026-08-05 09:45:27','2026-08-05 09:45:27'),(19,'countdown_subtitle_ar','منتدى المهارات الإفريقية 2026 — مركز المؤتمرات محمد بن أحمد - وهران','string','general',NULL,1,NULL,'2026-08-13 00:09:46','2026-08-13 00:09:46'),(20,'countdown_subtitle_fr','Africa Skills Forum 2026 — Centre des Conventions Mohamed Ben Ahmed - Oran','string','general',NULL,1,NULL,'2026-08-13 00:09:46','2026-08-13 00:09:46'),(21,'countdown_subtitle_en','Africa Skills Forum 2026 — Mohamed Ben Ahmed Convention Center - Oran','string','general',NULL,1,NULL,'2026-08-13 00:09:46','2026-08-13 00:09:46'),(22,'hero_title','افتتاح منتدى المهارات الإفريقية 2026','string','general',NULL,1,NULL,'2026-08-13 00:09:46','2026-08-13 00:09:46'),(23,'hero_subtitle','تجمع الوفود الوطنية والدولية والخبراء بمركز المؤتمرات محمد بن أحمد بولاية وهران.','string','general',NULL,1,NULL,'2026-08-13 00:09:46','2026-08-13 00:09:46'),(25,'guide_card2_image','/images/hero_slide_3.png','string','general',NULL,1,NULL,'2026-08-13 00:27:53','2026-08-13 00:27:53'),(26,'guide_card3_image','/images/hero_slide_2.png','string','general',NULL,1,NULL,'2026-08-13 00:27:53','2026-08-13 00:27:53'),(27,'accreditation_banner_image','/images/channels4_banner.jpg','string','general',NULL,1,NULL,'2026-08-13 00:27:53','2026-08-13 07:55:14'),(33,'hero_slides_count','3','string','general',NULL,1,NULL,'2026-08-13 00:33:03','2026-08-13 00:33:03'),(34,'venue_name_en','Mohamed Ben Ahmed Convention Center (CCO) — Oran, Algeria','string','general',NULL,1,NULL,'2026-08-13 00:42:48','2026-08-13 08:09:57'),(35,'venue_name_fr','Centre des Conventions Mohamed Ben Ahmed (CCO) — Oran, Algérie','string','general',NULL,1,NULL,'2026-08-13 00:42:48','2026-08-13 08:09:57'),(36,'venue_name','مركز المؤتمرات محمد بن أحمد (CCO) — وهران، الجزائر','string','general',NULL,1,NULL,'2026-08-13 00:42:48','2026-08-13 08:09:57'),(37,'countdown_timezone','Africa/Algiers','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(38,'countdown_status','COUNTDOWN','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(39,'countdown_theme','vintage_spiral_notebook','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(40,'countdown_digit_style','classic_mono','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(41,'countdown_color_sec','#0284C7','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(42,'countdown_color_min','#059669','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(43,'countdown_color_hrs','#D97706','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(44,'countdown_color_days','#7C3AED','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(45,'countdown_show_icons','1','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(46,'countdown_flip_animation','1','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(47,'show_partners_section','','string','general',NULL,1,NULL,'2026-08-14 13:28:19','2026-08-14 13:28:19'),(48,'official_registration_open','1','string','general',NULL,1,NULL,'2026-08-15 00:34:50','2026-08-15 00:40:06'),(49,'public_registration_open','1','string','general',NULL,1,NULL,'2026-08-15 00:39:09','2026-08-15 00:40:06'),(50,'forum.description_ar','يُنظَّم منتدى السياسات الأفريقية للمهارات بشراكة بين وزارة التكوين والتعليم المهنيين بالجزائر ومفوضية الاتحاد الأفريقي، ليكون الحدث السياسي الرفيع المستوى الرئيسي. يجمع المنتدى الوزراء الأفارقة المكلفين بالتكوين والتعليم المهنيين، إلى جانب الخبراء التقنيين والشركاء المؤسساتيين والدوليين، في برنامج عمل يقوم على الحوار الوزاري والتعاون القاري والالتزام السياسي المشترك.','string','general',NULL,1,NULL,'2026-08-18 12:07:49','2026-08-18 12:07:49'),(51,'forum.description_fr','Le Forum des Politiques Africaines des Compétences est co-organisé par le Ministère de la Formation et de l\'Enseignement Professionnels d\'Algérie et la Commission de l\'Union Africaine, constituant le principal événement politique de haut niveau. Le Forum réunit les ministres africains chargés de l\'EFTP, des experts techniques et des partenaires institutionnels internationaux pour un programme d\'action fondé sur le dialogue ministériel, la coopération continentale et l\'engagement politique conjoint.','string','general',NULL,1,NULL,'2026-08-18 12:07:49','2026-08-18 12:07:49'),(52,'forum.description_en','The African Skills Policy Forum is co-organized by Algeria\'s Ministry of Vocational Training and Education and the African Union Commission, serving as the principal high-level political summit. The Forum brings together African Ministers responsible for technical and vocational education and training, together with technical experts and institutional and international partners, for a working programme of ministerial dialogue, continental cooperation, and shared political commitment.','string','general',NULL,1,NULL,'2026-08-18 12:07:49','2026-08-18 12:07:49'),(53,'hero_bg_mode','image','string','general',NULL,1,NULL,'2026-08-18 20:40:53','2026-08-18 20:42:35');
